python3 - <<'PY'
import math
import datetime as dt
from datetime import timedelta
import openpyxl

SRC = '/root/Backup_Fuel_and_Refills_Latest.xlsx'
OUT = '/root/stochastic_refill_plan_october_2025.xlsx'

def to_date(v):
    if v is None:
        return None
    if isinstance(v, dt.datetime):
        return v.date()
    if isinstance(v, dt.date):
        return v
    if isinstance(v, str):
        s=v.strip()
        # try ISO
        try:
            return dt.date.fromisoformat(s)
        except Exception:
            # try common excel-like formats
            for fmt in ('%Y/%m/%d','%m/%d/%Y','%d/%m/%Y','%Y-%m-%d %H:%M:%S'):
                try:
                    return dt.datetime.strptime(s, fmt).date()
                except Exception:
                    pass
    raise ValueError(f'Unrecognized date value: {v!r} ({type(v)})')

wb = openpyxl.load_workbook(SRC, data_only=True)

# --- Current Fuel sheet mapping ---
ws_cf = wb['Current Fuel']
AsOfDate = to_date(ws_cf['B1'].value)
PlanningHorizonEnd = to_date(ws_cf['D1'].value)
RemainingDaysInOctober = (PlanningHorizonEnd - AsOfDate).days

# find header row for site table: expected in row 3
header_row = None
for r in range(1, ws_cf.max_row+1):
    vals=[ws_cf.cell(r,c).value for c in range(1, ws_cf.max_column+1)]
    if vals and 'Site_ID' in vals and 'Current_Liters' in vals and 'Expected_Daily_Burn_Liters' in vals and 'Daily_Burn_StdDev' in vals:
        header_row = r
        break
if header_row is None:
    raise RuntimeError('Could not find header row in Current Fuel sheet')

headers = {}
for c in range(1, ws_cf.max_column+1):
    v = ws_cf.cell(header_row,c).value
    if v is not None:
        headers[str(v).strip()] = c

required_cols = ['Site_ID','Current_Liters','Expected_Daily_Burn_Liters','Daily_Burn_StdDev']
for col in required_cols:
    if col not in headers:
        raise RuntimeError(f'Missing column {col} in Current Fuel table headers')

sites=[]
r = header_row+1
while r <= ws_cf.max_row:
    sid = ws_cf.cell(r, headers['Site_ID']).value
    if sid is None or str(sid).strip()=='' :
        break
    sid = str(sid).strip()
    def num(cell):
        v=cell.value
        if v is None or v=='':
            return 0
        return float(v) if isinstance(v,(int,float)) else float(str(v).strip())
    current = num(ws_cf.cell(r, headers['Current_Liters']))
    rate = num(ws_cf.cell(r, headers['Expected_Daily_Burn_Liters']))
    stddev = num(ws_cf.cell(r, headers['Daily_Burn_StdDev']))
    # preserve ints when possible
    current = int(current) if abs(current - int(current)) < 1e-9 else current
    rate = int(rate) if abs(rate - int(rate)) < 1e-9 else rate
    stddev = int(stddev) if abs(stddev - int(stddev)) < 1e-9 else stddev

    sites.append({
        'Site_ID': sid,
        'Current_Liters': current,
        'Expected_Daily_Burn_Liters': rate,
        'Daily_Burn_StdDev': stddev,
    })
    r += 1

# --- Scheduled Refills ---
ws_sr = wb['Scheduled Refills']
# header row at 1
sr_headers = {}
for c in range(1, ws_sr.max_column+1):
    v = ws_sr.cell(1,c).value
    if v is not None:
        sr_headers[str(v).strip()] = c

# identify columns
sid_col = sr_headers.get('Site_ID')
date_col = sr_headers.get('Refill Date') or sr_headers.get('Refill_Date') or sr_headers.get('Inbound Date')
# quantity liters column: prefer 'Liters'
qty_col = sr_headers.get('Liters') or sr_headers.get('Inbound Quantity') or sr_headers.get('Quantity')

if sid_col is None or date_col is None or qty_col is None:
    raise RuntimeError(f'Could not map Scheduled Refills columns. headers={sr_headers}')

refills=[]
for r in range(2, ws_sr.max_row+1):
    sid = ws_sr.cell(r, sid_col).value
    if sid is None or str(sid).strip()=='':
        continue
    sid=str(sid).strip()
    d = to_date(ws_sr.cell(r, date_col).value)
    qty = ws_sr.cell(r, qty_col).value
    if qty is None or qty=='':
        qty=0
    if not isinstance(qty,(int,float)):
        qty=float(str(qty).strip())
    # keep ints when possible
    qty = int(qty) if abs(qty - int(qty)) < 1e-9 else qty
    refills.append((sid, d, qty))

# --- Policy Parameters ---
ws_pp = wb['Policy Parameters']
# detect by header row 1
pp_headers = {}
for c in range(1, ws_pp.max_column+1):
    v = ws_pp.cell(1,c).value
    if v is not None:
        pp_headers[str(v).strip()] = c

liters_per_tanker_col = pp_headers.get('Liters_Per_Tanker')
service_z_col = pp_headers.get('Service_Level_Z')
if liters_per_tanker_col is None or service_z_col is None:
    raise RuntimeError(f'Could not map Policy Parameters columns. headers={pp_headers}')

Tanker_Capacity = ws_pp.cell(2, liters_per_tanker_col).value
Service_Level_Z = ws_pp.cell(2, service_z_col).value
if not isinstance(Tanker_Capacity,(int,float)):
    Tanker_Capacity = float(str(Tanker_Capacity).strip())
if not isinstance(Service_Level_Z,(int,float)):
    Service_Level_Z = float(str(Service_Level_Z).strip())

# --- computations ---
results=[]
for s in sites:
    site_id = s['Site_ID']
    current = float(s['Current_Liters'])
    rate = float(s['Expected_Daily_Burn_Liters'])
    stddev = float(s['Daily_Burn_StdDev'])

    if rate > 0:
        Current_DOH = current / rate
        Projected_Runout_Date = AsOfDate + timedelta(days=math.floor(Current_DOH))
    else:
        Current_DOH = None
        Projected_Runout_Date = None

    Inbound_Liters_By_Oct31 = sum(qty for (sid, d, qty) in refills if sid==site_id and d is not None and d <= PlanningHorizonEnd)
    if rate > 0:
        Delivered_DOH_To_Oct31 = (current + Inbound_Liters_By_Oct31) / rate
    else:
        Delivered_DOH_To_Oct31 = None

    Remaining_October_Burn_Liters = rate * RemainingDaysInOctober
    Safety_Buffer_Liters = Service_Level_Z * stddev * math.sqrt(RemainingDaysInOctober)

    Additional_Liters_Needed = max(0.0, Remaining_October_Burn_Liters + Safety_Buffer_Liters - current - Inbound_Liters_By_Oct31)

    if Additional_Liters_Needed > 0:
        Tankers_Required_Rounded_Up = int(math.ceil(Additional_Liters_Needed / Tanker_Capacity))
        # rounding applied only if not exact multiple
        Rounding_Applied = (Additional_Liters_Needed % Tanker_Capacity) != 0
    else:
        Tankers_Required_Rounded_Up = 0
        Rounding_Applied = False

    site_refill_dates = [d for (sid, d, qty) in refills if sid==site_id and d is not None]
    Earliest_Scheduled_Refill_Date = min(site_refill_dates) if site_refill_dates else None

    # Required_Refill_Date
    if Tankers_Required_Rounded_Up == 0 or rate <= 0:
        Required_Refill_Date = None
    elif Earliest_Scheduled_Refill_Date is not None and Projected_Runout_Date is not None and Earliest_Scheduled_Refill_Date <= Projected_Runout_Date:
        # use delivered DOH (as of Oct31) if scheduled refill happens before runout
        Required_Refill_Date = AsOfDate + timedelta(days=math.floor(Delivered_DOH_To_Oct31))
    else:
        Required_Refill_Date = Projected_Runout_Date

    if Tankers_Required_Rounded_Up > 0 and (Earliest_Scheduled_Refill_Date is None or (Required_Refill_Date is not None and Required_Refill_Date < Earliest_Scheduled_Refill_Date)):
        Earlier_Refill_Required = True
    else:
        Earlier_Refill_Required = False

    def keep_num(x):
        if x is None:
            return None
        if abs(x - int(x)) < 1e-9:
            return int(x)
        return float(x)

    results.append({
        'Site_ID': site_id,
        'Current_Liters': keep_num(current),
        'Expected_Daily_Burn_Liters': keep_num(rate),
        'Daily_Burn_StdDev': keep_num(stddev),
        'Current_DOH': None if Current_DOH is None else float(Current_DOH),
        'Projected_Runout_Date': Projected_Runout_Date,
        'Inbound_Liters_By_Oct31': keep_num(float(Inbound_Liters_By_Oct31)),
        'Delivered_DOH_To_Oct31': None if Delivered_DOH_To_Oct31 is None else float(Delivered_DOH_To_Oct31),
        'Remaining_October_Burn_Liters': keep_num(float(Remaining_October_Burn_Liters)),
        'Safety_Buffer_Liters': float(Safety_Buffer_Liters),
        'Additional_Liters_Needed': float(Additional_Liters_Needed),
        'Tankers_Required_Rounded_Up': int(Tankers_Required_Rounded_Up),
        'Required_Refill_Date': Required_Refill_Date,
        'Rounding_Applied': bool(Rounding_Applied),
        'Earlier_Refill_Required': bool(Earlier_Refill_Required),
        'Earliest_Scheduled_Refill_Date': Earliest_Scheduled_Refill_Date,
    })

# --- write output workbook ---
out_wb = openpyxl.Workbook()
# remove default sheet
if 'Sheet' in out_wb.sheetnames and len(out_wb.sheetnames)==1:
    out_wb.remove(out_wb['Sheet'])

ws1 = out_wb.create_sheet('Site_Results')
ws2 = out_wb.create_sheet('Additional_Refills_Needed')

# metadata on ws1
ws1['A1'] = 'Field'; ws1['B1'] = 'Value'
ws1['A2'] = 'AsOfDate'; ws1['B2'] = AsOfDate.isoformat() if AsOfDate else None
ws1['A3'] = 'PlanningHorizonEnd'; ws1['B3'] = PlanningHorizonEnd.isoformat() if PlanningHorizonEnd else None
ws1['A4'] = 'RemainingDaysInOctober'; ws1['B4'] = int(RemainingDaysInOctober)

headers_out = [
    'Site_ID','Current_Liters','Expected_Daily_Burn_Liters','Daily_Burn_StdDev','Current_DOH','Projected_Runout_Date',
    'Inbound_Liters_By_Oct31','Delivered_DOH_To_Oct31','Remaining_October_Burn_Liters','Safety_Buffer_Liters',
    'Additional_Liters_Needed','Tankers_Required_Rounded_Up','Required_Refill_Date','Rounding_Applied','Earlier_Refill_Required','Earliest_Scheduled_Refill_Date'
]
for i,h in enumerate(headers_out, start=1):
    ws1.cell(row=6, column=i, value=h)

# data rows start at 7
for idx, r in enumerate(results, start=7):
    for col_i, h in enumerate(headers_out, start=1):
        v = r[h]
        if h in ('Projected_Runout_Date','Required_Refill_Date','Earliest_Scheduled_Refill_Date'):
            v = v.isoformat() if isinstance(v, dt.date) else None
        ws1.cell(row=idx, column=col_i, value=v)

# Additional_Refills_Needed sheet
headers2 = ['Site_ID','Required_Refill_Date','Tankers_Required_Rounded_Up','Additional_Liters_Needed','Safety_Buffer_Liters','Rounding_Applied','Earlier_Refill_Required']
for i,h in enumerate(headers2, start=1):
    ws2.cell(row=1, column=i, value=h)

row_out=2
for r in results:
    if r['Tankers_Required_Rounded_Up']>0:
        for col_i,h in enumerate(headers2, start=1):
            v=r[h]
            if h=='Required_Refill_Date':
                v = v.isoformat() if isinstance(v, dt.date) else None
            ws2.cell(row=row_out, column=col_i, value=v)
        row_out += 1

# ensure only two sheets
for sname in list(out_wb.sheetnames):
    if sname not in ('Site_Results','Additional_Refills_Needed'):
        out_wb.remove(out_wb[sname])

out_wb.save(OUT)
print('Saved', OUT)
PY
